action.mutation:
mutation CreateOee($payload: [OeeCreatePayloadInput!]!) {
  mutation: createOee(payload: $payload) { 
    id
    id
  }
}

mutation UpdateOee($payload: [OeeUpdatePayloadInput!]!) {
  mutation: updateOee(payload: $payload) { 
    id
    id
  }
}

mutation DeleteOee($payload: [OeeDeletePayloadInput!]!) {
  mutation: deleteOee(payload: $payload) { 
    id
    id
  }
}
